solution.Program.cs:
using System.Globalization;

var lines = ReadAll();
var words = lines.SelectMany(Words).ToList();

Console.WriteLine($"Lines: {lines.Count}");
if (words.Count == 0)
{
    Console.WriteLine("No words.");
    return;
}
Console.WriteLine($"Words: {words.Count}");
Console.WriteLine($"Distinct words: {words.Distinct().Count()}");
Console.WriteLine($"Longest word: {Longest(words)}");
Console.WriteLine($"Average word length: {words.Average(w => w.Length).ToString("F2", CultureInfo.InvariantCulture)}");
PrintTopWords(words);
PrintLetters(lines);

static List<string> ReadAll()
{
    var all = new List<string>();
    string? line;
    while ((line = Console.ReadLine()) != null) all.Add(line);
    return all;
}

static IEnumerable<string> Words(string line)
{
    var word = new StringBuilder();
    foreach (char c in line.ToLowerInvariant())
    {
        if (char.IsLetter(c) || c == '\'') { word.Append(c); continue; }
        if (word.Length > 0) { yield return word.ToString(); word.Clear(); }
    }
    if (word.Length > 0) yield return word.ToString();
}

static string Longest(List<string> words)
{
    string best = words[0];
    foreach (string w in words) if (w.Length > best.Length) best = w;
    return best;
}

static void PrintTopWords(List<string> words)
{
    Console.WriteLine("Top words:");
    var top = words.GroupBy(w => w)
        .Select(g => (Word: g.Key, Count: g.Count()))
        .OrderByDescending(x => x.Count)
        .ThenBy(x => x.Word, StringComparer.Ordinal)
        .Take(5);
    foreach (var (word, count) in top) Console.WriteLine($"  {word,-12}{count,3}");
}

static void PrintLetters(List<string> lines)
{
    Console.WriteLine("Letters:");
    var counts = lines.SelectMany(l => l.ToLowerInvariant())
        .Where(c => c >= 'a' && c <= 'z')
        .GroupBy(c => c)
        .Select(g => (Letter: g.Key, Count: g.Count()))
        .OrderByDescending(x => x.Count)
        .ThenBy(x => x.Letter)
        .Take(5)
        .ToList();
    int highest = counts[0].Count;
    foreach (var (letter, count) in counts)
    {
        int width = Math.Max(1, count * 20 / highest);
        Console.WriteLine($"  {letter} {new string('#', width)} {count}");
    }
}
